nextflow_process {

    name "Test Process HAPPY_FTXPY"
    script "../main.nf"
    config "./nextflow.config"
    process "HAPPY_FTXPY"

    tag "modules"
    tag "modules_nfcore"
    tag "happy"
    tag "happy/ftxpy"

    test("homo_sapiens - illumina - mutect") {
        when {
            params {
                module_args = '--feature-table hcc.mutect.snv'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/gatk/paired_mutect2_calls/test_test2_paired_mutect2_calls.vcf.gz', checkIfExists: true),
                    [],
                    [],
                    []
                ]
                input[1] = [
                    [ id:'test2' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id:'test3' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr21/sequence/genome.fasta.fai', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }
        test("homo_sapiens - illumina - mutect - bam") {
        when {
            params {
                module_args = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
